pub fn read_uneven(stream: &mut ReadStream<'_>, value: &mut Uneven) -> Result {
    let mut tag_value: i32 = 0;
    stream.serialize_int(&mut tag_value, 0, 2)?; // rejects a tag above the count (SPEC §4.8)
    match tag_value {
        1 => {
            let mut arm = Narrow::default();
            read_narrow(stream, &mut arm)?;
            *value = Uneven::Narrow(arm);
        }
        2 => {
            let mut arm = Wide::default();
            read_wide(stream, &mut arm)?;
            *value = Uneven::Wide(arm);
        }
        _ => *value = Uneven::None,
    }
    Ok(())
}

// type HoldsUneven
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct HoldsUneven {
    pub lead: u32,
    pub u: Uneven,
    pub tail: u32,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for HoldsUneven {
    fn default() -> Self {
        HoldsUneven {
            lead: 0,
            u: Uneven::None,
            tail: 0,
        }
    }
}

// HOLDS_UNEVEN_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// HOLDS_UNEVEN_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const HOLDS_UNEVEN_MAX_BITS: u64 = 55;
pub const HOLDS_UNEVEN_MAX_BYTES: usize = 8;

#[inline(always)]
pub fn write_holds_uneven(stream: &mut WriteStream<'_>, value: &HoldsUneven) -> Result {
    if value.lead >= 1 << 5 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.lead;
        stream.serialize_bits(&mut raw_value, 5)?;
    }
    write_uneven(stream, &value.u)?;
    if value.tail >= 1 << 11 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.tail;
        stream.serialize_bits(&mut raw_value, 11)?;
    }
    Ok(())
}

#[inline]
pub fn read_holds_uneven(stream: &mut ReadStream<'_>, value: &mut HoldsUneven) -> Result {
    stream.serialize_bits(&mut value.lead, 5)?;
    read_uneven(stream, &mut value.u)?;
    stream.serialize_bits(&mut value.tail, 11)?;
    Ok(())
}

// type ArrUneven
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct ArrUneven {
    pub lead: u32,
    pub items: [Uneven; 3], // used count beside it; wire count in [0, 3]
    pub items_count: i32,
    pub tail: u32,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for ArrUneven {
    fn default() -> Self {
        ArrUneven {
            lead: 0,
            items: [Uneven::None; 3],
            items_count: 0,
            tail: 0,
        }
    }
}

// ARR_UNEVEN_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// ARR_UNEVEN_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const ARR_UNEVEN_MAX_BITS: u64 = 127;
pub const ARR_UNEVEN_MAX_BYTES: usize = 16;

#[inline(always)]
pub fn write_arr_uneven(stream: &mut WriteStream<'_>, value: &ArrUneven) -> Result {
    if value.lead >= 1 << 5 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.lead;
        stream.serialize_bits(&mut raw_value, 5)?;
    }
    if value.items_count < 0 || value.items_count > 3 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = value.items_count as u32;
        stream.serialize_bits(&mut offset_value, 2)?; // the count guards the loop (§6.3)
    }
    for i in 0..value.items_count as usize {
        write_uneven(stream, &value.items[i])?;
    }
    if value.tail >= 1 << 3 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.tail;
        stream.serialize_bits(&mut raw_value, 3)?;
    }
    Ok(())
}

#[inline]
pub fn read_arr_uneven(stream: &mut ReadStream<'_>, value: &mut ArrUneven) -> Result {
    stream.serialize_bits(&mut value.lead, 5)?;
    stream.serialize_int(&mut value.items_count, 0, 3)?; // the count guards the loop (§6.3)
    for i in 0..value.items_count as usize {
        read_uneven(stream, &mut value.items[i])?;
    }
    stream.serialize_bits(&mut value.tail, 3)?;
    Ok(())
}

// type RegainAfterAlign
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct RegainAfterAlign {
    pub lead: u32,
    pub items: [u16; 3], // used count beside it; wire count in [0, 3]
    pub items_count: i32,
    pub s: [u8; 4], // string(4): max length, used length beside it (SPEC §4.7)
    pub s_length: i32,
    pub p: u32,
    pub q: u32,
    pub r: u32,
    pub tail: u32,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for RegainAfterAlign {
    fn default() -> Self {
        RegainAfterAlign {
            lead: 0,
            items: [0; 3],
            items_count: 0,
            s: [0; 4],
            s_length: 0,
            p: 0,
            q: 0,
            r: 0,
            tail: 0,
        }
    }
}

// REGAIN_AFTER_ALIGN_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// REGAIN_AFTER_ALIGN_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const REGAIN_AFTER_ALIGN_MAX_BITS: u64 = 172;
pub const REGAIN_AFTER_ALIGN_MAX_BYTES: usize = 24;

#[inline(always)]
pub fn write_regain_after_align(stream: &mut WriteStream<'_>, value: &RegainAfterAlign) -> Result {
    if value.lead >= 1 << 5 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.lead;
        stream.serialize_bits(&mut raw_value, 5)?;
    }
    if value.items_count < 0 || value.items_count > 3 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = value.items_count as u32;
        stream.serialize_bits(&mut offset_value, 2)?; // the count guards the loop (§6.3)
    }
    for i in 0..value.items_count as usize {
        if value.items[i] > 8191 {
            return Err(Error::Stream(serialize::Error::ValueOutOfRange));
        }
        {
            let mut offset_value = value.items[i] as u32;
            stream.serialize_bits(&mut offset_value, 13)?;
        }
    }
    if value.s_length < 0 || value.s_length > 4 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    debug_assert!(
        std::str::from_utf8(&value.s[..value.s_length as usize]).is_ok(),
        "string(N) payloads are well-formed UTF-8 by contract (SPEC 4.7)"
    );
    {
        let mut offset_value = value.s_length as u32;
        stream.serialize_bits(&mut offset_value, 3)?; // the length guards the slice (§6.3)
    }
    stream.write_bytes(&value.s[..value.s_length as usize]); // borrowed in place: the write side never mutates (infallible: returns () in serialize.rs 2.0.0)
    if value.q >= 1 << 29 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    if value.r >= 1 << 19 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    if value.tail >= 1 << 4 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    let f0: u64 = u64::from(value.p);
    let f1: u64 = u64::from(value.q);
    let f2: u64 = u64::from(value.r);
    let f3: u64 = u64::from(value.tail);
    let mut w0 = f0 as u32;
    stream.serialize_bits(&mut w0, 32)?;
    let mut w1 = (f1 | (f2 << 29)) as u32;
    stream.serialize_bits(&mut w1, 32)?;
    let mut w2 = ((f2 >> 3) | (f3 << 16)) as u32;
    stream.serialize_bits(&mut w2, 20)?;
    Ok(())
}

#[inline]
pub fn read_regain_after_align(stream: &mut ReadStream<'_>, value: &mut RegainAfterAlign) -> Result {
    stream.serialize_bits(&mut value.lead, 5)?;
    stream.serialize_int(&mut value.items_count, 0, 3)?; // the count guards the loop (§6.3)
    for i in 0..value.items_count as usize {
        {
            let mut range_value: i32 = 0;
            stream.serialize_int(&mut range_value, 0, 8191)?;
            value.items[i] = range_value as u16;
        }
    }
    stream.serialize_int(&mut value.s_length, 0, 4)?; // the length guards the slice (§6.3)
    stream.serialize_bytes(&mut value.s[..value.s_length as usize])?;
    for i in 0..value.s_length as usize {
        if value.s[i] == 0 {
            return Err(Error::Validation);
        }
    }
    let mut c: u32 = 0;
    stream.serialize_bits(&mut c, 32)?;
    let c0 = u64::from(c);
    stream.serialize_bits(&mut c, 32)?;
    let c1 = u64::from(c);
    stream.serialize_bits(&mut c, 20)?;
    let c2 = u64::from(c);
    let v0: u64 = c0 & 0xffffffff;
    value.p = v0 as u32;
    let v1: u64 = c1 & 0x1fffffff;
    value.q = v1 as u32;
    let v2: u64 = ((c1 >> 29) | (c2 << 3)) & 0x7ffff;
    value.r = v2 as u32;
    let v3: u64 = (c2 >> 16) & 0xf;
    value.tail = v3 as u32;
    Ok(())
}

